export const SCRIPTS: { code: string; exports: string[] }[] = [{"code":"\n  // ── Supabase config (your live project) ──────────────────────────────────────\n  const SUPABASE_URL = \"https://kwxlfuygotdcabhkqbdd.supabase.co\";\n  const SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imt3eGxmdXlnb3RkY2FiaGtxYmRkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODI4MjY2NzksImV4cCI6MjA5ODQwMjY3OX0.ECebrh77wy-OCa44s10aH1HLsykCRBq4s1rGIFipdm4\";\n\n  // ── Edge Function URL — fill this in after deploying ─────────────────────────\n  // Format: https://kwxlfuygotdcabhkqbdd.supabase.co/functions/v1/send-application-email\n  const EDGE_FUNCTION_URL = \"https://kwxlfuygotdcabhkqbdd.supabase.co/functions/v1/send-application-email\";\n\n const supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);\n\n  function calcAgeFromDob(dobStr) {\n    if (!dobStr) return null;\n    const dob = new Date(dobStr);\n    const today = new Date();\n    let age = today.getFullYear() - dob.getFullYear();\n    const m = today.getMonth() - dob.getMonth();\n    if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) age--;\n    return age;\n  }\n\n  (function setDobBounds() {\n    const dobInput = document.getElementById('talentpool-dob-input');\n    if (!dobInput) return;\n    const today = new Date();\n    const maxDob = new Date(today.getFullYear() - 18, today.getMonth(), today.getDate());\n    const minDob = new Date(today.getFullYear() - 100, today.getMonth(), today.getDate());\n    const toISO = d => {\n      const y = d.getFullYear();\n      const m = String(d.getMonth() + 1).padStart(2, '0');\n      const day = String(d.getDate()).padStart(2, '0');\n      return `${y}-${m}-${day}`;\n    };\n    dobInput.setAttribute('max', toISO(maxDob));\n    dobInput.setAttribute('min', toISO(minDob));\n\n    const errorEl = document.getElementById('dob-inline-error');\n    dobInput.addEventListener('change', () => {\n      const age = calcAgeFromDob(dobInput.value);\n      if (age === null) { errorEl.style.display = 'none'; return; }\n      if (age < 18) {\n        errorEl.textContent = 'You must be at least 18 years old to join the talent pool.';\n        errorEl.style.display = 'block';\n      } else if (age > 100) {\n        errorEl.textContent = 'Please double-check the date of birth entered.';\n        errorEl.style.display = 'block';\n      } else {\n        errorEl.style.display = 'none';\n      }\n    });\n  })();\n\n  // ── Assessment question banks ────────────────────────────────────────────────\n  const ANNOTATION_QUESTIONS = [\n    { name: \"q1\", label: \"1. Explain what image annotation means and why accuracy matters.\", type: \"textarea\" },\n    { name: \"q2\", label: \"2. An object is partially hidden in an image. How would you decide whether to annotate it?\", type: \"textarea\" },\n    { name: \"q3\", label: \"3. If annotation instructions are unclear, what steps would you take?\", type: \"textarea\" },\n    { name: \"q4\", label: \"4. Two annotators label the same image differently. How would you resolve the difference?\", type: \"textarea\" },\n    { name: \"q5\", label: \"5. What methods do you use to maintain accuracy during repetitive annotation work?\", type: \"textarea\" },\n    { name: \"q6\", label: \"6. Which approach best describes correct bounding-box annotation?\", type: \"select\", options: [\n      \"Box drawn loosely around the general area of the object\",\n      \"Box drawn tightly to the visible edges of the object, including visible occluded parts\",\n      \"Box drawn only around the most visible 50% of the object\",\n      \"Box skipped if the object is partially hidden\"\n    ]},\n    { name: \"q7\", label: \"7. You review a labeled image and find an object category is wrong but the box placement is correct. What's the best action?\", type: \"select\", options: [\n      \"Leave it as is since the box is correct\",\n      \"Delete the annotation entirely\",\n      \"Correct the category label while keeping the accurate box\",\n      \"Flag the entire image as unusable\"\n    ]}\n  ];\n\n  const QUALITY_QUESTIONS = [\n    { name: \"q1\", label: \"1. What makes an image high quality?\", type: \"textarea\" },\n    { name: \"q2\", label: \"2. Compare two images mentally from a recent project you've seen — explain how you'd decide which is better and why.\", type: \"textarea\" },\n    { name: \"q3\", label: \"3. Rate how important each factor is to you when evaluating images (Realism, Sharpness, Lighting, Composition, Accuracy) — explain your priority order.\", type: \"textarea\" },\n    { name: \"q4\", label: \"4. Which of these is NOT typically a visual defect to flag in AI-generated images?\", type: \"select\", options: [\n      \"Blur or distortion\",\n      \"Incorrect or extra objects\",\n      \"Natural lighting variation across a scene\",\n      \"Unrealistic anatomical or structural details\"\n    ]},\n    { name: \"q5\", label: \"5. When two images are close in quality, what should guide your final decision?\", type: \"select\", options: [\n      \"Personal preference only\",\n      \"Whichever image was generated first\",\n      \"Objective criteria: realism, clarity, composition, and accuracy against the brief\",\n      \"Image file size\"\n    ]},\n    { name: \"q6\", label: \"6. Explain your reasoning process when selecting the better of two similar images.\", type: \"textarea\" }\n  ];\n\n  // ── Build dynamic assessment questions ──────────────────────────────────────\n  function buildQuestions(list) {\n    const container = document.getElementById('assessment-questions');\n    container.innerHTML = '<div class=\"form-section-label\">Assessment</div>';\n    list.forEach(q => {\n      const block = document.createElement('div');\n      block.className = 'question-block';\n      const label = document.createElement('label');\n      label.textContent = q.label;\n      block.appendChild(label);\n      if (q.type === 'textarea') {\n        const ta = document.createElement('textarea');\n        ta.name = q.name; ta.required = true;\n        block.appendChild(ta);\n      } else if (q.type === 'select') {\n        const sel = document.createElement('select');\n        sel.name = q.name; sel.required = true;\n        sel.innerHTML = '<option value=\"\">Select…</option>' + q.options.map(o => `<option>${o}</option>`).join('');\n        block.appendChild(sel);\n      }\n      container.appendChild(block);\n    });\n  }\n\n  // ── Open modal (checks job_settings table first) ─────────────────────────────\n  async function openAssessment(type) {\n    const jobName = type === \"annotation\"\n      ? \"Image Annotation Specialist\"\n      : \"Image Quality Assessment Specialist\";\n\n    const { data, error } = await supabaseClient\n      .from(\"job_settings\")\n      .select(\"is_open\")\n      .eq(\"job_name\", jobName)\n      .single();\n\n    if (error) {\n      console.error(error);\n      alert(\"Unable to check application status. Please try again.\");\n      return;\n    }\n\n    if (!data.is_open) {\n      alert(\"Applications for this position are currently closed. Join our talent pool to be notified when it opens.\");\n      return;\n    }\n\n    const titleEl = document.getElementById('modal-title');\n    const subEl   = document.getElementById('modal-sub');\n    const posField = document.getElementById('position-field');\n    document.getElementById('assessment-form').reset();\n    document.getElementById('form-msg').className = 'form-msg';\n\n    if (type === 'annotation') {\n      titleEl.textContent = 'Image Annotation Specialist — Application';\n      subEl.textContent   = 'Tell us about yourself and complete the annotation assessment below.';\n      posField.value      = 'Image Annotation Specialist';\n      buildQuestions(ANNOTATION_QUESTIONS);\n    } else {\n      titleEl.textContent = 'Image Quality Assessment Specialist — Application';\n      subEl.textContent   = 'Tell us about yourself and complete the image quality assessment below.';\n      posField.value      = 'Image Quality Assessment Specialist';\n      buildQuestions(QUALITY_QUESTIONS);\n    }\n\n    document.getElementById('assessment-modal').classList.add('open');\n    document.body.style.overflow = 'hidden';\n  }\n\n  function closeAssessment() {\n    document.getElementById('assessment-modal').classList.remove('open');\n    document.body.style.overflow = '';\n  }\n\n  document.getElementById('assessment-modal').addEventListener('click', function(e) {\n    if (e.target === this) closeAssessment();\n  });\n\n  // ── Form submission ──────────────────────────────────────────────────────────\n  document.getElementById('assessment-form').addEventListener('submit', async function(e) {\n    e.preventDefault();\n    const msg       = document.getElementById('form-msg');\n    const submitBtn = document.getElementById('submit-btn');\n\n    submitBtn.disabled    = true;\n    submitBtn.textContent = 'Submitting…';\n    msg.className         = 'form-msg';\n\n    try {\n      const form       = e.target;\n      const formData   = new FormData(form);\n      const resumeFile = document.getElementById('resume-input').files[0];\n\n      // File size guard\n      if (resumeFile && resumeFile.size > 10 * 1024 * 1024) {\n        throw new Error('Resume file exceeds 10MB. Please upload a smaller file.');\n      }\n\n      // Upload resume to Supabase Storage\n      let resumePath = null;\n      if (resumeFile) {\n        const safeName = `${Date.now()}_${resumeFile.name.replace(/[^a-zA-Z0-9.\\-_]/g, '_')}`;\n        const { data: uploadData, error: uploadError } = await supabaseClient\n          .storage.from('resumes').upload(safeName, resumeFile);\n        if (uploadError) throw uploadError;\n        resumePath = uploadData.path;\n      }\n\n      // Collect assessment answers\n      const answers = {};\n      formData.forEach((value, key) => {\n        if (/^q\\d+$/.test(key)) answers[key] = value;\n      });\n\n      const now = new Date().toISOString();\n\n      const payload = {\n        position:             formData.get('position'),\n        full_name:            formData.get('full_name'),\n        email:                formData.get('email'),\n        phone:                formData.get('phone'),\n        country:              formData.get('country'),\n        city:                 formData.get('city'),\n        timezone:             formData.get('timezone'),\n        occupation:           formData.get('occupation'),\n        previous_experience:  formData.get('previous_experience'),\n        years_experience:     formData.get('years_experience'),\n        exp_annotation:       !!formData.get('exp_annotation'),\n        exp_labeling:         !!formData.get('exp_labeling'),\n        exp_ai_training:      !!formData.get('exp_ai_training'),\n        exp_qa:               !!formData.get('exp_qa'),\n        exp_image_eval:       !!formData.get('exp_image_eval'),\n        languages:            formData.get('languages'),\n        computer_skills:      formData.get('computer_skills'),\n        internet_availability: formData.get('internet_availability'),\n        hours_per_week:       formData.get('hours_per_week'),\n        resume_path:          resumePath,\n        assessment_answers:   answers,\n        status:               'Submitted',\n        submitted_at:         now\n      };\n\n      // 1. Insert into applications table\n      const { error: insertError } = await supabaseClient.from('applications').insert([payload]);\n      if (insertError) throw insertError;\n\n      // 2. Fire Edge Function to send emails (non-blocking — submission is safe even if this fails)\n      fetch(EDGE_FUNCTION_URL, {\n        method: 'POST',\n        headers: {\n          'Content-Type': 'application/json',\n          'Authorization': `Bearer ${SUPABASE_ANON_KEY}`\n        },\n        body: JSON.stringify({\n          full_name:    payload.full_name,\n          email:        payload.email,\n          position:     payload.position,\n          submitted_at: now\n        })\n      }).catch(err => console.warn('Email notification failed (non-blocking):', err));\n\n      msg.textContent = 'Thank you — your application and assessment have been received. We will be in touch by email.';\n      msg.className   = 'form-msg success show';\n      form.reset();\n      setTimeout(closeAssessment, 2500);\n\n    } catch (err) {\n      msg.textContent = 'Something went wrong: ' + (err.message || 'please try again or contact us directly.');\n      msg.className   = 'form-msg error show';\n    } finally {\n      submitBtn.disabled    = false;\n      submitBtn.textContent = 'Submit application →';\n    }\n  });\n\n// ── Talent pool modal ────────────────────────────────────────────────────────\n  function openTalentPool() {\n    document.getElementById('talentpool-form').reset();\n    document.getElementById('talentpool-form-msg').className = 'form-msg';\n    document.getElementById('talentpool-modal').classList.add('open');\n    document.body.style.overflow = 'hidden';\n  }\n\n  function closeTalentPool() {\n    document.getElementById('talentpool-modal').classList.remove('open');\n    document.body.style.overflow = '';\n  }\n\n  document.getElementById('talentpool-modal').addEventListener('click', function(e) {\n    if (e.target === this) closeTalentPool();\n  });\n\n  document.getElementById('talentpool-form').addEventListener('submit', async function(e) {\n    e.preventDefault();\n    const msg       = document.getElementById('talentpool-form-msg');\n    const submitBtn = document.getElementById('talentpool-submit-btn');\n\n    submitBtn.disabled    = true;\n    submitBtn.textContent = 'Submitting…';\n    msg.className         = 'form-msg';\n\n    try {\n      const form       = e.target;\n      const formData   = new FormData(form);\n      const resumeFile = document.getElementById('talentpool-resume-input').files[0];\n\n      const dobValue = formData.get('date_of_birth');\n      const age = calcAgeFromDob(dobValue);\n      if (age === null || age < 18) {\n        throw new Error('You must be at least 18 years old to join the talent pool.');\n      }\n      if (age > 100) {\n        throw new Error('Please double-check the date of birth entered.');\n      }\n\n      if (resumeFile && resumeFile.size > 10 * 1024 * 1024) {\n        throw new Error('Resume file exceeds 10MB. Please upload a smaller file.');\n      }\n\n      let resumePath = null;\n      if (resumeFile) {\n        const safeName = `${Date.now()}_${resumeFile.name.replace(/[^a-zA-Z0-9.\\-_]/g, '_')}`;\n        const { data: uploadData, error: uploadError } = await supabaseClient\n          .storage.from('resumes').upload(safeName, resumeFile);\n        if (uploadError) throw uploadError;\n        resumePath = uploadData.path;\n      }\n\n      const now = new Date().toISOString();\n\n      const payload = {\n        full_name:              formData.get('full_name'),\n        email:                  formData.get('email'),\n        phone:                  formData.get('phone'),\n        gender:                 formData.get('gender'),\n        date_of_birth:          dobValue,\n\n        // Positions interested in\n        pos_software_dev:       !!formData.get('pos_software_dev'),\n        pos_data_annotator:     !!formData.get('pos_data_annotator'),\n        pos_ai_trainer:         !!formData.get('pos_ai_trainer'),\n        pos_uiux:               !!formData.get('pos_uiux'),\n        pos_marketing:          !!formData.get('pos_marketing'),\n        pos_support:            !!formData.get('pos_support'),\n        pos_pm:                 !!formData.get('pos_pm'),\n        pos_finance:            !!formData.get('pos_finance'),\n        pos_hr:                 !!formData.get('pos_hr'),\n        pos_other:              !!formData.get('pos_other'),\n        pos_other_specify:      formData.get('pos_other_specify') || null,\n\n        years_experience:       formData.get('years_experience'),\n        education_level:        formData.get('education_level'),\n        education_background:   formData.get('education_background'),\n\n        // Skills\n        skill_programming:      !!formData.get('skill_programming'),\n        skill_annotation:       !!formData.get('skill_annotation'),\n        skill_ai_ml:            !!formData.get('skill_ai_ml'),\n        skill_design:           !!formData.get('skill_design'),\n        skill_support:          !!formData.get('skill_support'),\n        skill_marketing:        !!formData.get('skill_marketing'),\n        skill_admin:            !!formData.get('skill_admin'),\n        skill_writing:          !!formData.get('skill_writing'),\n        skill_finance:          !!formData.get('skill_finance'),\n        skill_other:            !!formData.get('skill_other'),\n\n        work_type:              formData.get('work_type'),\n        availability:           formData.get('availability'),\n        areas_of_expertise:     formData.get('areas_of_expertise'),\n        computer_spec:          formData.get('computer_spec'),\n        referred_by:            formData.get('referred_by'),\n        country:                formData.get('country'),\n        efset_certificate_url:  formData.get('efset_certificate_url'),\n        resume_path:            resumePath,\n        additional_experience:  formData.get('additional_experience') || null,\n        status:                 'In pool',\n        submitted_at:           now\n      };\n\n      const { error: insertError } = await supabaseClient.from('talent_pool').insert([payload]);\n      if (insertError) {\n    console.error(insertError);\n    alert(JSON.stringify(insertError, null, 2));\n    throw insertError;\n}\n\n      msg.textContent = 'Thank you — you\\'ve been added to our talent pool. We\\'ll reach out when a matching role opens.';\n      msg.className   = 'form-msg success show';\n      form.reset();\n      setTimeout(closeTalentPool, 2500);\n\n    } catch (err) {\n      msg.textContent = 'Something went wrong: ' + (err.message || 'please try again or contact us directly.');\n      msg.className   = 'form-msg error show';\n    } finally {\n      submitBtn.disabled    = false;\n      submitBtn.textContent = 'Submit to talent pool →';\n    }\n  });\n","exports":["calcAgeFromDob","buildQuestions","openAssessment","closeAssessment","openTalentPool","closeTalentPool"]}];
